import React from "react";
import { useNavigate } from "react-router-dom";

const Hero = () => {
  const navigate = useNavigate();

  return (
    <section className="hero">

      <div className="container">

        {/* LEFT SIDE */}
        <div className="left">

          <p className="tag">WELCOME</p>

          <h1>
            I'm <span className="name">Swetha A</span>
          </h1>

          <h2 className="role">
            Full Stack Developer • System Thinker • Problem Solver
          </h2>

          <p className="desc">
            I enjoy building scalable systems, clean UI experiences, and real-world
            applications that solve meaningful problems through structured thinking.
          </p>

          <div className="buttons">
            <button className="btn primary" onClick={() => navigate("/projects")}>
              Explore Projects →
            </button>

            <button className="btn secondary" onClick={() => navigate("/about")}>
              About Me →
            </button>
          </div>

        </div>

        {/* RIGHT SIDE - PASSION FLOW (MIND MAP) */}
        <div className="right">

          <div className="passion">

            <h3>My Career Mindset</h3>

            <div className="node center">Passion for Technology</div>

            <div className="row">
              <div className="node">Problem Solving</div>
              <div className="node">Building Systems</div>
              <div className="node">Continuous Learning</div>
            </div>

            <div className="node bottom">
              Creating Real-World Impact
            </div>

          </div>

        </div>

      </div>

      <style>{`

        .hero {
          min-height: 100vh;
          display: flex;
          align-items: center;
          background: radial-gradient(circle at top, #0b1220, #050816);
          padding: 0 8%;
        }

        .container {
          display: grid;
          grid-template-columns: 1.2fr 1fr;
          gap: 60px;
          width: 100%;
          align-items: center;
        }

        /* LEFT SIDE */
        .tag {
          font-size: 12px;
          letter-spacing: 3px;
          color: #64748b;
          margin-bottom: 15px;
        }

        h1 {
          font-size: 62px;
          margin: 0;
        }

        .name {
          color: #38BDF8;
          letter-spacing: 1px;
        }

        .role {
          font-size: 20px;
          color: #94a3b8;
          margin-top: 10px;
        }

        .desc {
          margin-top: 18px;
          font-size: 16px;
          color: #cbd5e1;
          line-height: 1.7;
          max-width: 520px;
        }

        .buttons {
          margin-top: 30px;
          display: flex;
          gap: 15px;
        }

        .btn {
          padding: 12px 22px;
          border-radius: 10px;
          cursor: pointer;
          transition: 0.3s;
          font-weight: 600;
          border: 1px solid rgba(56,189,248,0.3);
        }

        .primary {
          background: #38BDF8;
          color: #0b1220;
        }

        .primary:hover {
          transform: translateY(-2px);
        }

        .secondary {
          background: rgba(255,255,255,0.03);
          color: #38BDF8;
        }

        .secondary:hover {
          background: rgba(56,189,248,0.08);
        }

        /* RIGHT SIDE - PASSION FLOW */
        .passion {
          display: flex;
          flex-direction: column;
          align-items: center;
          justify-content: center;
          height: 320px;
          text-align: center;
        }

        .passion h3 {
          color: #38BDF8;
          margin-bottom: 25px;
          font-size: 18px;
          letter-spacing: 1px;
        }

        .node {
          padding: 10px 14px;
          border-radius: 12px;
          background: rgba(255,255,255,0.04);
          border: 1px solid rgba(56,189,248,0.15);
          font-size: 13px;
          color: #cbd5e1;
          transition: 0.3s;
        }

        .node:hover {
          transform: translateY(-4px);
          border-color: rgba(56,189,248,0.4);
        }

        .center {
          font-weight: 600;
          color: #38BDF8;
          margin-bottom: 18px;
        }

        .row {
          display: flex;
          gap: 10px;
          margin: 10px 0;
          flex-wrap: wrap;
          justify-content: center;
        }

        .bottom {
          margin-top: 18px;
          color: #38BDF8;
          font-weight: 500;
        }

        /* RESPONSIVE */
        @media (max-width: 900px) {
          .container {
            grid-template-columns: 1fr;
            text-align: center;
          }

          .buttons {
            justify-content: center;
          }

          h1 {
            font-size: 42px;
          }

          .passion {
            margin-top: 40px;
          }
        }

      `}</style>

    </section>
  );
};

export default Hero;
